class NewContactAddressEntryForm extends ConsumerStatefulWidget {
  const NewContactAddressEntryForm({
    super.key,
    required this.id,
    required this.clipboard,
  });

  final int id;

  final ClipboardInterface clipboard;

  @override
  ConsumerState<NewContactAddressEntryForm> createState() =>
      _NewContactAddressEntryFormState();
}

class _NewContactAddressEntryFormState
    extends ConsumerState<NewContactAddressEntryForm> {
  late final TextEditingController addressController;

  late final FocusNode addressFocusNode;

  /// Coins an address may belong to; the address picks its coin (PIVX
  /// mainnet and testnet addresses differ), so no coin selector.
  List<CryptoCurrency> coins = [];

  void _setAddress(String? address) {
    final data = ref.read(addressEntryDataProvider(widget.id));
    final a = address?.trim() ?? "";
    data.coin = a.isEmpty
        ? null
        : coins.where((c) => c.validateAddress(a)).firstOrNull;
    data.address = a.isEmpty ? null : a;
  }

  void _onQrTapped() async {
    try {
      final qrResult = await ref.read(pBarcodeScanner).scan(context: context);
      if (qrResult.rawContent == null) return;

      final paymentData = AddressUtils.parsePaymentUri(
        qrResult.rawContent!,
        logging: Logging.instance,
      );

      if (paymentData != null) {
        addressController.text = paymentData.address;
        _setAddress(addressController.text);

        // now check for non standard encoded basic address
      } else if (coins.any((c) => c.validateAddress(qrResult.rawContent!))) {
        addressController.text = qrResult.rawContent!;
        _setAddress(qrResult.rawContent);
      }
    } on PlatformException catch (e, s) {
      if (mounted) {
        try {
          await checkCamPermDeniedMobileAndOpenAppSettings(
            context,
            logging: Logging.instance,
          );
        } catch (e, s) {
          Logging.instance.e(
            "Failed to check cam permissions",
            error: e,
            stackTrace: s,
          );
        }
      } else {
        Logging.instance.w(
          "Failed to get camera permissions to scan address qr code: ",
          error: e,
          stackTrace: s,
        );
      }
    }
  }

  @override
  void initState() {
    addressController = TextEditingController()
      ..text = ref.read(addressEntryDataProvider(widget.id)).address ?? "";
    addressFocusNode = FocusNode();
    coins = shownCoins(ref, withWalletCoins: true);
    super.initState();
  }

  @override
  void dispose() {
    addressController.dispose();
    addressFocusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final isDesktop = Util.isDesktop;

    return Column(
      children: [
        ClipRRect(
          borderRadius: BorderRadius.circular(
            Constants.size.circularBorderRadius,
          ),
          child: TextField(
            enableSuggestions: Util.isDesktop ? false : true,
            focusNode: addressFocusNode,
            controller: addressController,
            style: STextStyles.field(context),
            decoration:
                standardInputDecoration(
                  l10n.contactPasteAddress,
                  addressFocusNode,
                  context,
                ).copyWith(
                  labelStyle: isDesktop
                      ? STextStyles.fieldLabel(context)
                      : null,
                  suffixIcon: UnconstrainedBox(
                    child: Row(
                      children: [
                        if (ref.watch(
                              addressEntryDataProvider(widget.id)
                                  .select((value) => value.address),
                            ) !=
                            null)
                          TextFieldIconButton(
                            key: const Key(
                              "addAddressBookClearAddressButtonKey",
                            ),
                            onTap: () async {
                              addressController.text = "";
                              _setAddress(null);
                            },
                            child: const XIcon(),
                          ),
                        if (ref.watch(
                              addressEntryDataProvider(widget.id)
                                  .select((value) => value.address),
                            ) ==
                            null)
                          TextFieldIconButton(
                            key: const Key("addAddressPasteAddressButtonKey"),
                            onTap: () async {
                              final ClipboardData? data = await widget.clipboard
                                  .getData(Clipboard.kTextPlain);

                              if (data?.text != null &&
                                  data!.text!.isNotEmpty) {
                                String content = data.text!.trim();
                                if (content.contains("\n")) {
                                  content = content.substring(
                                    0,
                                    content.indexOf("\n"),
                                  );
                                }
                                addressController.text = content;
                                _setAddress(content);
                              }
                            },
                            child: const ClipboardIcon(),
                          ),
                        if (!Util.isDesktop &&
                            ref.watch(
                                  addressEntryDataProvider(widget.id)
                                      .select((value) => value.address),
                                ) ==
                                null)
                          TextFieldIconButton(
                            key: const Key(
                              "addAddressBookEntryScanQrButtonKey",
                            ),
                            onTap: _onQrTapped,
                            child: const QrCodeIcon(),
                          ),
                        const SizedBox(width: 8),
                      ],
                    ),
                  ),
                ),
            key: const Key("addAddressBookEntryViewAddressField"),
            readOnly: false,
            autocorrect: false,
            toolbarOptions: const ToolbarOptions(
              copy: false,
              cut: false,
              paste: true,
              selectAll: false,
            ),
            onChanged: _setAddress,
          ),
        ),
        if (!ref.watch(
              addressEntryDataProvider(widget.id)
                  .select((value) => value.isValidAddress),
            ) &&
            addressController.text.isNotEmpty)
          Row(
            children: [
              const SizedBox(width: 12),
              Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const SizedBox(height: 4),
                  Text(
                    l10n.sendInvalidAddress,
                    textAlign: TextAlign.left,
                    style: STextStyles.label(context).copyWith(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .textError,
                    ),
                  ),
                ],
              ),
            ],
          ),
      ],
    );
  }
}
